Phat_shifter - Angel2 fingre.warp:
shader_body
{
texsize.xy=texsize.zw*3;
float2 muv=uv;
//uv=uv_orig;
float3 lluu = GetPixel(float2(uv.x-texsize.x*2,uv.y-texsize.y*2));
float3 luu  = GetPixel(float2(uv.x-texsize.x,uv.y-texsize.y*2));
float3 lu   = GetPixel(float2(uv.x-texsize.x,uv.y-texsize.y));
float3 rruu = GetPixel(float2(uv.x+texsize.x*2,uv.y-texsize.y*2));
float3 ruu  = GetPixel(float2(uv.x+texsize.x,uv.y-texsize.y*2));
float3 ru   = GetPixel(float2(uv.x+texsize.x,uv.y-texsize.y));
float3 lldd = GetPixel(float2(uv.x-texsize.x*2,uv.y+texsize.y*2));
float3 ldd  = GetPixel(float2(uv.x-texsize.x,uv.y+texsize.y*2));
float3 ld   = GetPixel(float2(uv.x-texsize.x,uv.y+texsize.y));
float3 rrdd = GetPixel(float2(uv.x+texsize.x*2,uv.y+texsize.y*2));
float3 rdd  = GetPixel(float2(uv.x+texsize.x,uv.y+texsize.y*2));
float3 rd   = GetPixel(float2(uv.x+texsize.x,uv.y+texsize.y));
//ret-=((lu+luu+lu)*(1-lluu))*0.1;
//uncomment upper - kinda new look.
ret+=1.2*(rd+rdd+rrdd+ld+ldd+lldd+ru+ruu+rruu+lu+lluu+luu)/12;
float4 noise9 = tex3D(sampler_noisevol_hq, 
                      ((uv.xyy*q27
                       )*texsize.xyy*texsize_noisevol_hq.zww
                      ).xyz*
                      float3(1,1,0)*0.05 + 
                      time*float3(0,0,1)*q29
                     );
if(ret.x> q21*q13         && ret.x<= q24*q11        )ret.y += (noise9).x*.5; 
if(ret.y> q22*q11         && ret.y<= q25*q12        )ret.z += (noise9).y*.5; 
if(ret.z> q23*q12         && ret.z<= q26*q13        )ret.x += (noise9).z*.5; 
ret-=GetBlur1(uv)*0.5;
ret/=1+(rd+ld+lu+ld)*0.01;
ret*=1.1;
//try
//ret+=0.05;
//instead of
ret+=0.1*(0.5-tex2D(sampler_noise_lq,uv_orig*rand_frame.xy*9));

}

Phat_shifter - Angel2 fingre.comp:
shader_body
{
float3 rnd = tex2D(sampler_noise_lq, rand_frame.xy + uv*texsize.xy*texsize_noise_lq.zw)*2-1;

ret = GetPixel(uv);
float4 noise9 = tex3D(sampler_noisevol_hq, 
                      ((uv.xyy*q28
                       )*texsize.xyy*texsize_noisevol_hq.zww
                      ).xyz*
                      float3(1,1,0)*0.05 + 
                      time*float3(0,0,1)*q31
                     );
if(ret.x> q26*q13         && ret.x<= q23*q11        )ret.z -= (noise9).x*.5; 
if(ret.y> q25*q11         && ret.y<= q22*q12        )ret.x -= (noise9).y*.5; 
if(ret.z> q24*q12         && ret.z<= q21*q13        )ret.y -= (noise9).z*.5; 
float2 d = texsize.zw * 8;
float3 dx = ( GetBlur1(uv + float2(1,0)*d) - GetBlur1(uv-float2(1,0)*d) );
float3 dy = ( GetBlur1(uv + float2(0,1)*d) - GetBlur1(uv-float2(0,1)*d) );

uv -= float2(lum(dx),lum(dy))*texsize.zw*32;


ret = pow(abs(GetBlur3(uv+rnd.xy*texsize.zw*5)*2-GetPixel(uv))*1.6,2)*0.9;

}

