if (ret.z < .09) {
ret*=0;
}


}

suksma - beyond imbalance understate - d.comp:
sampler sampler_fw_noise_hq;
float z;
float3 ret1, neu, mus;
float2 rs,rs2,uv1,uv2, uv3,uv4,uv6,dz,dz1;
shader_body
{
float2 uv2;
//uv = (uv-0.5) * aspect.xy + .5;    
dz = 0;


float2 hor = float2(texsize.z,0);
float2 ver = float2(0,texsize.w);

float dist = 1;
float inten = 1;
ret1 = 0;
float anz = 1;
float n = 0;

    float4 N1 = tex2D(sampler_fw_noise_hq, uv*texsize.xy*.1*texsize_noise_hq.zw/64 +rand_preset.xy)*1;
    float4 N2 = tex2D(sampler_fw_noise_hq, uv*texsize.xy*.1*texsize_noise_hq.zw/16+rand_preset.xy)*0.25;
    float4 N3 = tex2D(sampler_fw_noise_hq, uv*texsize.xy*.1*texsize_noise_hq.zw/32+rand_preset.xy)*0.5;

    uv = 0.05 + 0.9*uv;
    uv.x += 0.05*cos((N1.x + N2.x + N3.x)*5 + bass_att*.2+time*4.13);
    uv.y += 0.05*sin((N1.y + N2.y + N3.y)*5 + treb_att*.2+time*5);
uv4 = (uv);
    dz.x = lum(GetPixel(uv4+hor)- GetPixel (uv4-hor));
    dz.y = lum(GetPixel(uv4+ver)- GetPixel (uv4-ver));

//uv4 = 0;

mus = .5*GetPixel(uv4+.1*dz)+0*dz.x+.01;

uv2 = uv-.5;
while (n <= anz) {
    dist = 1-frac(1.0/anz*n-.1); //evtl sqrt !;

    inten =  sqrt(dist)*(1-dist*dist)*4;

    uv3 = 2*uv2*dist + .5 + 0.0*time;

//    uv3 *= aspect.yx;
    uv3 = frac(uv3);

    uv3 = .2 * cos(42*uv3+time/2) + 99*dz;
    neu = saturate(.01/length(uv3)) ;
    neu = dist*neu + (1-dist)*lum(neu);
    ret1 = max(ret1,neu*inten);
n++;
}


ret = ret1  +  saturate(16*mus*(.1+ret1));
}

