    float2 d = texsize.zw*2;
    float3 dx = ( GetBlur1(uv + float2(1,0)*d) - GetBlur1(uv-float2(1,0)*d) );
    float3 dy = ( GetBlur1(uv + float2(0,1)*d) - GetBlur1(uv-float2(0,1)*d) );
    float2 my_uv = uv + float2(dx.y,dy.y)*0.05;
    float grad = length(my_uv-uv)*32;
    float emboss = (dx.y+dy.y)*4 + 0.5;

    float2 uv_echo =  0.5 + (uv-0.5) * float2(-1,1) + float2(dx.y,dy.y)*0.05;
    float3 bird = max( tex2D(sampler_main, my_uv).x, tex2D(sampler_main, uv_echo).x);
           bird = pow(bird,1.4)*pow(hue_shader,2);

    float3 bg = emboss*float3(0,0,1) + float3(2,3,0)*grad + float3(1,0,0)*base.y - float3(0,0,0.3);
           bg = bg*0.6*saturate(1 - bird.x*4);

    float3 wave = GetBlur1(uv+float2(dx.y,dy.y)*0.1)*saturate(1-bird.x*0);

ret = bg + bird;
ret = lerp(ret, 1, wave.z*6*(1-bird*3));

}

