shader_body
{
    float2 d = texsize.zw*4.5;
    float3 dx = ( GetBlur1(uv + float2(1,0)*d) - GetBlur1(uv-float2(1,0)*d) );
    float3 dy = ( GetBlur1(uv + float2(0,1)*d) - GetBlur1(uv-float2(0,1)*d) );

    float2 uv_dy = uv_orig + (float2(dx.x, dy.x)*q11 + float2(dx.y, dy.y)*q12 + float2(dx.z, dy.z)*q13)*texsize.zw*6;
//    float2 uv_dy = uv_orig + float2(dx.y, dy.y)*texsize.zw*6;

    ret = GetPixel(uv_dy) + (GetPixel(uv) - GetBlur1(uv))*0.1 - .004*pow(GetPixel(uv).x*GetPixel(uv).y*GetPixel(uv).z, .333)/q9 - (0.0008*q28*(sqrt(treb)*GetPixel(uv).x*GetPixel(uv).y + sqrt(mid)*GetPixel(uv).x*GetPixel(uv).z + sqrt(bass)*GetPixel(uv).y*GetPixel(uv).z));
//    ret = GetPixel(uv_dy) + (GetPixel(uv) - GetBlur1(uv))*0.1 - .016;
//    ret += (tex2D(sampler_pw_main, uv_orig)-0.5)*.0043;

ret.x = lerp(ret.x, 1.1*tex2D(sampler_pc_main, uv_orig).x, bass_att*.1);
ret.y = lerp(ret.y, 1.1*tex2D(sampler_pc_main, uv_orig).y, mid_att*.1);
ret.z = lerp(ret.z, 1.1*tex2D(sampler_pc_main, uv_orig).z, treb_att*.1);

//    ret.x += .012*(sqrt(bass_att)*sqrt(2.3*(1.1*tex2D( sampler_pc_main, uv_orig ).x - .5)));
