//    ret.z += .012*(sqrt(treb_att)*sqrt(2.3*(1.1*tex2D( sampler_pc_main, uv_orig ).z - .5)));
    ret += mul(pow(q3, 1.25), .013*tex2D( sampler_pw_main, uv ));
}

