float hq_n (float3 uvi) {return lum(tex2D (sampler_noise_hq ,uvi.xy));}
float noise2 (float3 uvi) {return tex2D (sampler_noise_lq,uvi*8);}

float noise4 (float2 uvi) { float n1,n2,n3,n4,zv; zv = 0.006*time;
  n1 = lum(tex2D(sampler_noise_hq, (uvi)));
  n2 = lum(tex2D(sampler_noise_hq, (uvi*2+zv)));
  n3 = lum(tex2D(sampler_noise_hq, (uvi*4+zv)));
  n4 = lum(tex2D(sampler_noise_hq, (uvi*8+4*zv)));
  return n1 + n2/2 + n3/4 + n4/8;}

float noise3 (float3 uvi) {float arg;
return  clamp(tex2D (sampler_noise_hq,uvi.xy/16)-.5,-.25,.25)*2
        +(tex2D (sampler_noise_hq,uvi.xy/8)-.5)/4
        +(tex2D (sampler_noise_hq,(uvi.x-sin(uvi.y*2))/2))/12;}

float3 rs_lav (float2 uvi, float berg) {  float z; float2 rs;
  z = 8/(uvi.y)*(q8-4*berg); z = clamp(z,-8,80*hordist); //#final check !
  rs.x = uvi.x*z ; rs.y = z; 
  rs = mul(rs,float2x2(q3,q4,-q4,q3));  
  return float3(rs/64 + mov,z); } 

float3 rs_sky (float2 uvi, float berg) {  float z; float2 rs;
  z = 8/(uvi.y - berg-.5); z = clamp(z,-32,1);
  rs.x = (uvi.x)*z ; rs.y = z; 
