{
float2 uv2=uv;
uv2.x=1-uv2.x;
    uv = 0.05 + 0.9*uv;
    uv2 = 0.05 + 0.9*uv2;

ret = GetPixel(uv);
float3 ret2 = GetPixel(uv2);
    uv += -.05*tan(3*(ret.zz+ret.yx));
    uv2 += -.05*tan(3*(ret2.zz+ret2.yx));


