mid_avg = tic*(mid_avg*(1/tic - 10) + 10*mid);
bass_avg = tic*(bass_avg*(1/tic - 10) + 10*bass);
vav = tic*(vav*(1/tic - 10) + 10*(bass+treb+mid)*.33333);

tt = tt + tic*treb;
mt = mt + tic*mid;

