toc = 1;


tr = if(above(st,0),.999,tr + tic*mid);
tr = tr - int(tr);
st = if(above(st,0),st - tic,above(tr,.9)*.1);


q1 = tt; // speed of comets
q2 = bt; // speed of ripples
//q2 = .5;
q3 = (tt + mt)*.1; //speed of bands
q4 = vt; // speed of rotation

br = beatrate*.5;
sw = above(tim,br);
tim = if(sw,tim-br,tim);
